import{_ as n,o as r,c as u,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Den Zeugnisdruck vorbereiten","description":"","frontmatter":{"title":"Den Zeugnisdruck vorbereiten","source_pageid":1619,"source_revision":6861},"headers":[],"relativePath":"reporting/zeugnisformulare/zeugnisse-themenuebersicht.md","filePath":"reporting/zeugnisformulare/zeugnisse-themenuebersicht.md"}'),i={name:"reporting/zeugnisformulare/zeugnisse-themenuebersicht.md"};function a(l,e,t,o,g,h){return r(),u("div",null,[...e[0]||(e[0]=[s('<h1 id="den-zeugnisdruck-vorbereiten" tabindex="-1">Den Zeugnisdruck vorbereiten <a class="header-anchor" href="#den-zeugnisdruck-vorbereiten" aria-label="Permalink to &quot;Den Zeugnisdruck vorbereiten&quot;">​</a></h1><p>Gehen Sie vom passenden Zeugnispaket über die Bereitstellung und Konfiguration zum Druck. Für schulformspezifische Abläufe und den Gruppendruck führen die Verweise zu den jeweiligen Anleitungen.</p><p><a href="/reporting/reportdesigner/reportdesigner-schnelleinstieg.html">Den passenden Einstieg in den Reportdesigner finden</a></p><h2 id="zeugnisse" tabindex="-1">Zeugnisse <a class="header-anchor" href="#zeugnisse" aria-label="Permalink to &quot;Zeugnisse&quot;">​</a></h2><p>Auf unseren Internetseiten finden Sie Zeugnisformulare aller Schulformen. Die Zeugnisformulare wurden alle rechtlich geprüft und werden regelmäßig an neue Vorgaben angepasst. Diese Seite erleichtert Ihnen den Einstieg im Umgang mit den Zeugnisformularen. Lesen Sie hier, wo Zeugnisse heruntergeladen und wie diese aktualisiert werden können.</p><h3 id="zeugnisse-herunterladen-und-aktualisieren" tabindex="-1">Zeugnisse herunterladen und aktualisieren <a class="header-anchor" href="#zeugnisse-herunterladen-und-aktualisieren" aria-label="Permalink to &quot;Zeugnisse herunterladen und aktualisieren&quot;">​</a></h3><ul><li><a href="/reporting/zeugnisformulare/zeugnispakete-auf-github.html">Zeugnispakete nach Schulform auswählen</a></li></ul><p>Links zu allen Zeugnispaketen aller Schulformen</p><ul><li><a href="/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html">Zeugnisformulare herunterladen und bereitstellen</a></li></ul><p>Schritt-für-Schritt-Anleitung</p><h3 id="schulformspezifischer-zeugnisdruck" tabindex="-1">Schulformspezifischer Zeugnisdruck <a class="header-anchor" href="#schulformspezifischer-zeugnisdruck" aria-label="Permalink to &quot;Schulformspezifischer Zeugnisdruck&quot;">​</a></h3><ul><li><a href="/zeugnisse/berufskolleg/erstellen-von-abschlusszeugnissen-am-bk-tutorial.html" title="Erstellen von Abschlusszeugnissen am BK">Abschlusszeugnisse am Berufskolleg</a></li></ul><p>Erstellen Sie Abschlusszeugnisse am BK</p><ul><li><a href="/zeugnisse/grundschule/grundschulzeugnisse-hybridzeugnis-tutorial.html" title="Grundschulzeugnisse Hybridzeugnis">Grundschul-Hybridzeugnis</a></li></ul><p>Erstellen Sie Grundschulzeugnisse mit fachbezogener Kompetenzbeschreibung und Noten</p><h3 id="inhalt-und-layout-anpassen" tabindex="-1">Inhalt und Layout anpassen <a class="header-anchor" href="#inhalt-und-layout-anpassen" aria-label="Permalink to &quot;Inhalt und Layout anpassen&quot;">​</a></h3><ul><li><a href="/reporting/zeugnisformulare/inhalt-layout-von-zeugnissen-konfigurieren.html">Inhalt und Layout von Zeugnissen konfigurieren</a></li></ul><p>INI-Dateien anpassen, um Zeugnisse zu ändern</p><h3 id="zeugnis-als-broschure" tabindex="-1">Zeugnis als Broschüre <a class="header-anchor" href="#zeugnis-als-broschure" aria-label="Permalink to &quot;Zeugnis als Broschüre&quot;">​</a></h3><ul><li><a href="/zeugnisse/vorbereitung/zeugnis-broschuerendruck-mit-dem-foxit-reader-tutorial.html" title="Zeugnis-Broschürendruck mit dem Foxit Reader">Zeugnis-Broschürendruck</a></li></ul><p>Drucken Sie doppelseitige Zeugnisse als Broschüre mit externem Hilfsprogramm</p><h3 id="zeugnisdruck-als-gruppenprozess" tabindex="-1">Zeugnisdruck als Gruppenprozess <a class="header-anchor" href="#zeugnisdruck-als-gruppenprozess" aria-label="Permalink to &quot;Zeugnisdruck als Gruppenprozess&quot;">​</a></h3><ul><li><a href="/zeugnisse/vorbereitung/zeugnisvorlagen-zuordnen-schulbezogene-kataloge.html" title="Zeugnisvorlagen zuordnen (Schulbezogene Kataloge)">Zeugnisformulare zuordnen</a></li></ul><p>Vereinfachen Sie den Zeugnisdruck, indem Sie passende Zeugnisse den Jahrgängen zuordnen</p><ul><li><a href="/zeugnisse/vorbereitung/zugeordnete-zeugnisformulare-drucken-gruppenprozesse-noten-zeugnisvorbereitung.html" title="Zugeordnete Zeugnisformulare drucken (Gruppenprozesse Noten, Zeugnisvorbereitung)">Zugeordnete Zeugnisformulare drucken</a></li></ul><p>Drucken Sie Zeugnisse passend zu den Jahrgängen</p><ul><li><a href="/zeugnisse/vorbereitung/zeugnisse-drucken-und-schueler-ausschulen-gruppenprozesse-noten-zeugnisvorbereitung.html" title="Zeugnisse drucken und Schüler ausschulen (Gruppenprozesse Noten, Zeugnisvorbereitung)">Zeugnisse drucken und Schüler ausschulen</a></li></ul><p>Zeugnisdruck und Statusänderung in einem Vorgang</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zeugnisse_Themen%C3%BCbersicht" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6861.</p>',30)])])}const p=n(i,[["render",a]]);export{c as __pageData,p as default};
